  "version": "0.1.0",
  "description": "Keyless Microsoft Entra ID (Azure AD) authentication plugin for opencode - authenticate Azure AI Foundry and Azure Databricks model endpoints with az CLI tokens instead of API keys",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "type": "module",
  "license": "MIT",
  "author": "Byungsu Kim",
