  },
  "homepage": "https://github.com/bskim/opencode-azure-entra-auth#readme",
  "bugs": {
    "url": "https://github.com/bskim/opencode-azure-entra-auth/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "plugin",
    "auth",
    "azure",
    "entra",
    "azure-ad",
    "foundry",
    "databricks",
    "keyless"
  ],
  "scripts": {
    "build": "tsc",
    "typecheck": "tsc --noEmit"
  },
  "files": [
