    "typescript": "^5.9.3"
  }
}

import type { Plugin } from "@opencode-ai/plugin"
import { execFile } from "node:child_process"

/**
 * Per-provider configuration.
 *
 * `resource` is the Azure AD token resource (audience) requested from the
 * Azure CLI for that provider. Examples:
 *   - Azure AI Foundry / Cognitive Services: "https://cognitiveservices.azure.com"
 *   - Azure Databricks (global app id):       "2ff814a6-3304-4ab8-85cb-cd0e6f879c1d"
 */
export interface ProviderAuthConfig {
  resource: string
  /**
   * When true, normalize sampling params for Azure reasoning models that
   * reject `max_tokens` and only allow temperature=1 (e.g. GPT-5.x on Foundry).
   * Defaults to false.
   */
  reasoningParamFix?: boolean
}

export interface AzureEntraAuthOptions {
  /** Map of opencode provider id -> auth config. */
  providers: Record<string, ProviderAuthConfig>
  /**
   * Override the Azure CLI executable. Defaults to "az".
   */
  azCommand?: string
}

/**
 * ─── EDIT THIS WHEN INSTALLING AS A LOCAL PLUGIN ─────────────────────────────
 *
 * opencode auto-loads files in `~/.config/opencode/plugins/` without passing
 * options, so when you use this file as a local plugin, set your provider →
 * Entra-token-resource mapping here. (When the plugin is loaded as an npm
 * package with an options tuple, those options take precedence and this map is
 * ignored.)
 *
 * Keys are opencode provider ids; `resource` is the Azure AD token resource
 * (audience) for that provider.
 */
const DEFAULT_PROVIDERS: Record<string, ProviderAuthConfig> = {
  // foundry: { resource: "https://cognitiveservices.azure.com", reasoningParamFix: true },
  // databricks: { resource: "2ff814a6-3304-4ab8-85cb-cd0e6f879c1d" },
}

interface CachedToken {
  token: string
  expiresAtMs: number
}

const SKEW_MS = 5 * 60 * 1000 // refresh this long before expiry

const cache = new Map<string, CachedToken>()

function azToken(azCommand: string, resource: string, attempt = 0): Promise<CachedToken> {
  return new Promise((resolve, reject) => {
    execFile(
      azCommand,
      ["account", "get-access-token", "--resource", resource, "--output", "json"],
      { shell: true, windowsHide: true, maxBuffer: 1024 * 1024 },
      (err, stdout, stderr) => {
        if (err) {
          const msg = `${stderr || err.message || ""}`
          const needsLogin = /AADSTS|az login|not logged in|refresh token|re-?authenticate|expired/i.test(msg)
          if (needsLogin) {
            return reject(
              new Error(
                "Azure sign-in required for opencode model auth. Run `az login` " +
                  "(interactive) or `az login --service-principal ...` / use a Managed " +
                  `Identity for unattended runs. Underlying error: ${msg.trim()}`,
              ),
            )
          }
          if (attempt < 2) {
            setTimeout(() => azToken(azCommand, resource, attempt + 1).then(resolve, reject), 400 * (attempt + 1))
            return
          }
          return reject(new Error(`az token failed (${resource}): ${msg.trim()}`))
        }
        try {
          const j = JSON.parse(stdout) as { accessToken: string; expiresOn: string }
          resolve({ token: j.accessToken, expiresAtMs: new Date(j.expiresOn).getTime() })
        } catch (e) {
          reject(new Error(`failed to parse az output: ${(e as Error).message}`))
        }
      },
    )
  })
}

async function getToken(azCommand: string, providerId: string, resource: string, forceRefresh = false): Promise<string> {
  const cached = cache.get(providerId)
  if (!forceRefresh && cached && cached.expiresAtMs - SKEW_MS > Date.now()) return cached.token
  const fresh = await azToken(azCommand, resource)
  cache.set(providerId, fresh)
  return fresh.token
}

function makeAuthedFetch(azCommand: string, providerId: string, resource: string): typeof fetch {
  const base = globalThis.fetch
  return async (input: Parameters<typeof fetch>[0], init: Parameters<typeof fetch>[1] = {}) => {
    const headers = new Headers(init?.headers || {})
    headers.set("Authorization", `Bearer ${await getToken(azCommand, providerId, resource)}`)
    let res = await base(input, { ...init, headers })
    if (res.status === 401 || res.status === 403) {
      const retryHeaders = new Headers(init?.headers || {})
      retryHeaders.set("Authorization", `Bearer ${await getToken(azCommand, providerId, resource, true)}`)
      res = await base(input, { ...init, headers: retryHeaders })
    }
    return res
  }
}

/**
 * opencode plugin: authenticate Azure model providers with Microsoft Entra ID
 * (Azure AD) tokens from the Azure CLI, instead of storing API keys on disk.
 */
export const AzureEntraAuth: Plugin = async (_input, options) => {
  const opts = (options || {}) as Partial<AzureEntraAuthOptions>
  const providers = opts.providers && Object.keys(opts.providers).length > 0 ? opts.providers : DEFAULT_PROVIDERS
  const azCommand = opts.azCommand || "az"
  const ids = Object.keys(providers)

  return {
    config: async (config: any) => {
      const configured = config?.provider
      if (!configured) return
      for (const providerId of ids) {
        const p = configured[providerId]
        if (!p) continue
        p.options = p.options || {}
        p.options.fetch = makeAuthedFetch(azCommand, providerId, providers[providerId].resource)
      }
    },

    "chat.params": async (input: any, output: any) => {
      const providerId = input?.provider?.id
      if (!providerId || !providers[providerId]?.reasoningParamFix) return
      output.maxOutputTokens = undefined
      output.temperature = 1
      output.topP = 1
    },
  }
}

export default AzureEntraAuth
